// Mark all faces as exterior initially
for (Triangulation::All_faces_iterator fit = triangulation.all_faces_begin();
     fit != triangulation.all_faces_end(); ++fit) {
    fit->info().interior = false;
    fit->info().processed = false;
}

// Find an infinite face to start the exterior flood-fill
Triangulation::Face_handle infinite_face = triangulation.infinite_face();
std::queue<Triangulation::Face_handle> face_queue;
face_queue.push(infinite_face);
infinite_face->info().processed = true;

// Flood-fill exterior faces
while (!face_queue.empty()) {
    Triangulation::Face_handle current_face = face_queue.front();
    face_queue.pop();

    for (int i = 0; i < 3; ++i) {
        Triangulation::Face_handle neighbor = current_face->neighbor(i);
        if (!triangulation.is_infinite(neighbor) && !neighbor->info().processed) {
            // Check if edge is constrained
            if (!triangulation.is_constrained(std::make_pair(current_face, i))) {
                neighbor->info().processed = true;
                face_queue.push(neighbor);
            }
        }
    }
}

// Now mark remaining unprocessed faces as interior
for (Triangulation::Finite_faces_iterator fit = triangulation.finite_faces_begin();
     fit != triangulation.finite_faces_end(); ++fit) {
    if (!fit->info().processed) {
        fit->info().interior = true;
    }
    fit->info().processed = false; // Reset for later use
}

